CREATE TABLE IF NOT EXISTS customer_orders (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), customer_name TEXT NOT NULL, phone TEXT NOT NULL, email TEXT NOT NULL DEFAULT '', fulfillment TEXT NOT NULL CHECK (fulfillment IN ('delivery','pickup')), address TEXT NOT NULL DEFAULT '', notes TEXT NOT NULL DEFAULT '', items JSONB NOT NULL, subtotal NUMERIC(12,2) NOT NULL, total NUMERIC(12,2) NOT NULL, status TEXT NOT NULL DEFAULT 'new' CHECK (status IN ('new','confirmed','preparing','completed','cancelled')), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());